-- Expands dm_reactions.emoji from the fixed 6-string CHECK constraint to
-- accepting any emoji the full picker (frimousse) can actually produce,
-- backing the full picker added alongside the existing 6 quick reactions.
--
-- Policy — an exact-membership lookup against a versioned catalogue, NOT a
-- hand-rolled Unicode structural parser. An earlier version of this
-- migration walked each string code point by code point against a curated
-- range allowlist; that approach rejected valid sequences it had no rule
-- for (subdivision flags like England/Scotland/Wales use TAG characters,
-- U+E0000-E007F, an entirely different mechanism from the two-regional-
-- indicator country flags the walker knew about) and accepted malformed
-- ones its adjacency rule didn't actually rule out (a leading/trailing ZWJ,
-- or two joined sequences that are each individually well-formed but not a
-- real combination). A general-purpose Unicode emoji-sequence parser
-- correct enough to avoid both failure modes is a significant undertaking
-- to hand-maintain; an exact lookup against the real catalogue the picker
-- draws from sidesteps needing one at all — validity is "does this exact
-- string appear in a table," not "does this string satisfy a set of rules
-- approximating the spec."
--
-- dm_supported_emoji is generated by scripts/generate-emoji-catalogue.mjs
-- from the SAME self-hosted emojibase-data file the picker's own runtime
-- reads (public/emoji-data/en/data.json) — the base `emoji` field plus
-- every `skins[].emoji` variant (frimousse computes skin-tone strings from
-- that same per-entry metadata, not as separately-listed top-level
-- entries) — so "every emoji selectable in the picker" and "every emoji
-- the database accepts" are the same set by construction, not by
-- convention. Each row is tagged with `source_version` (the emojibase-data
-- release the row came from), making the catalogue's own provenance
-- queryable.
--
-- Newer/unsupported Unicode Emoji versions: a version NOT yet reflected in
-- this catalogue is rejected (fails closed) until the catalogue is
-- regenerated and shipped as a new forward migration adding those rows —
-- there is no partial/best-effort acceptance of an emoji this table
-- doesn't know about. Deployment order for a catalogue refresh: 1) update
-- public/emoji-data (new emojibase-data release) and re-run the generator
-- script, which rewrites the block below with the new emoji list against a
-- LOCAL/dev database first; 2) ship a NEW migration containing only the
-- newly-added rows (never edit rows already shipped in an applied
-- migration); 3) deploy the app build referencing the updated
-- public/emoji-data alongside it, so the picker and the validator move
-- together.
create table dm_supported_emoji (
  emoji text primary key,
  source_version text not null
);
revoke all on dm_supported_emoji from public, anon, authenticated;

-- BEGIN GENERATED CATALOGUE (scripts/generate-emoji-catalogue.mjs) --
